return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n >= 2 && n <= 4) ? 1 : 2);','language'=>'cs_CZ','project-id-version'=>'Plugins - Kybernaut IČO DIČ - Stable (latest release)','pot-creation-date'=>'2026-10-25T18:01:39+00:00','po-revision-date'=>'2026-10-25T21:38:13+00:00','x-generator'=>'GlotPress/4.1.0','messages'=>['Adds Czech Company & VAT numbers (IČO & DIČ) to WooCommerce billing fields and verifies if data are correct.'=>'Přidá IČO a DIČ do formuláře s fakturační adresou ve WooCommerce a ověří jejich platnost.','View GitHub'=>'Zobrazit na GitHubu','GitHub'=>'GitHub','Write a Review'=>'Ohodnotit','View Kybernaut IČO DIČ settings'=>'Zobrazit nastavení Kybernaut IČO DIČ','Settings'=>'Nastavení','Business ID is invalid.'=>'IČO není platné.','Unexpected error occurred. Try it again.'=>'Nastala neočekávaná chyba. Zkuste to prosím znovu.','Clear company details'=>'Vymazat údaje o firmě','Validating data in ARES.'=>'Ověřuji data v ARESu.','Information loaded succesfully from ARES.'=>'Informace byly úspěšně načteny z ARESu.','Validating data in Finančná správa.'=>'Ověřuji data v seznamech Finanční správy SR.','Information loaded succesfully from Finančná správa.'=>'Informace byly úspěšně načteny z Finanční správy SR.','Validating data in %s.'=>'Ověřuji data v registru %s.','Information loaded successfully from %s.'=>'Informace byly úspěšně načteny z registru %s.','Turn on "%s" first.'=>'Nejprve zapněte „%s“.','CZ: Validate Business ID in ARES'=>'CZ: Ověřit IČO v ARESu','SK: Validate in Finančná správa'=>'SK: Ověřit v seznamech Finanční správy SR','Turn on at least one of the ARES, Finančná správa or VIES checks first.'=>'Nejprve zapněte alespoň jedno z ověření v ARESu, v seznamech Finanční správy SR nebo ve VIES.','Buying as a company'=>'Nakupuji na firmu','Reverse charge: the order is without VAT, the buyer accounts for it.'=>'Přenesení daňové povinnosti: objednávka je bez DPH, DPH odvede odběratel.','This tax number is valid. Without the country code (%s) it is not an EU VAT ID, so the order is placed with VAT.'=>'Toto daňové číslo je platné, bez kódu země (%s) to však není DIČ pro účely DPH v EU, objednávka se proto vytvoří s DPH.','This %s is not registered for VAT in the EU (VIES), so the order is placed with VAT.'=>'Toto %s není registrováno k DPH v EU (VIES), objednávka se proto vytvoří s DPH.','Business ID'=>'IČO','Tax ID'=>'DIČ','VAT reg. no.'=>'IČ DPH','Czech DIČ fieldVAT ID'=>'DIČ','EU VAT number fieldVAT ID'=>'DIČ','Slovak IČ DPH fieldVAT ID'=>'IČ DPH','optional, only if you are a VAT payer'=>'volitelné, jen pokud jste plátce DPH','label before a value%s: '=>'%s: ','Verification of VAT number has failed.'=>'Ověření DIČ se nezdařilo.','Caution!'=>'Pozor!','Please, make sure the VAT number is valid before processing the order.'=>'Před zpracováním objednávky se ujistěte, že je DIČ platné.','Business ID not set.'=>'IČO není vyplněno.','Business ID must be a number and 8 digits long.'=>'IČO musí být osmimístné číslo.','An error occured while connecting to ARES, try it again later.'=>'Při připojování k ARESu došlo k chybě, zkuste to prosím později.','Entity doesn\'t exist in ARES.'=>'Uvedené IČO neexistuje v ARESu.','ARES is not responding.'=>'ARES neodpovídá.','Finančná správa lists are not available.'=>'Seznamy Finanční správy SR nejsou dostupné.','Business ID not found in Finančná správa, fill in the details manually.'=>'IČO se v seznamech Finanční správy SR nenašlo, vyplňte prosím údaje ručně.','Kybernaut IČO DIČ: the Finančná správa DIČ / IČ DPH lists are missing or older than a week, so those numbers cannot be validated. The import runs daily through WP-Cron (or run "wp woolab-icdic sk-import"); failures are logged in WooCommerce → Status → Logs.'=>'Kybernaut IČO DIČ: seznamy DIČ / IČ DPH Finanční správy SR chybí nebo jsou starší než týden, proto tato čísla nelze ověřit. Import běží denně přes WP-Cron (nebo spusťte „wp woolab-icdic sk-import“); chyby se zapisují do WooCommerce → Stav → Protokoly.','Kybernaut IČO DIČ: the Finančná správa DIČ / IČ DPH lists cannot be imported, the zip, xmlreader and pdo_sqlite PHP extensions are required (ask your hosting).'=>'Kybernaut IČO DIČ: seznamy DIČ / IČ DPH Finanční správy SR nelze importovat, chybí PHP rozšíření zip, xmlreader a pdo_sqlite (obraťte se na poskytovatele hostingu).','Import status'=>'Stav importu','This feature is not compatible with Fluid Checkout for WooCommerce.'=>'Tato funkce není kompatibilní s pluginem Fluid Checkout for WooCommerce.','Kybernaut IČO DIČ options'=>'Nastavení Kybernaut IČO DIČ','The following options affect how Business ID and VAT number behaves.'=>'Následující možnosti ovlivní, jak se bude chovat ověřování IČO a DIČ.','Toggle fields visibility'=>'Viditelnost polí','Enable toggle switch to show/hide input fields'=>'Povolit přepínač pro zobrazení/skrytí polí IČO, DIČ a Firma','Move Country to top'=>'Přesunout „Země“ na začátek','Move Country field above the "Buying as a company" toggle'=>'Přesunout pole „Země“ nad zaškrtávací pole „Nakupuji na firmu“','Company fields'=>'Firemní pole','The company name and the Business ID (in the Czech Republic and Slovakia, where every company has one). "Required for companies" works best with the toggle: without it, a filled-in company name makes the customer a company. The DIČ of the shop\'s own country follows it only with "Require DIČ". The VAT ID stays optional, abroad with "only if you are a VAT payer".'=>'Název firmy a IČO (v Česku a na Slovensku, kde ho má každá firma). „Povinné pro firmy“ funguje nejlépe s přepínačem: bez něj se za firmu považuje každý zákazník, který vyplní název firmy. DIČ firem ze země obchodu se tímto nastavením řídí, jen když je zapnuto „Vyžadovat DIČ“. Jinak je DIČ volitelné, u zahraničních firem s poznámkou „jen pokud jste plátce DPH“.','Optional: "(optional)", as WooCommerce marks fields'=>'Volitelné: „(volitelné)“, jak pole označuje WooCommerce','No mark: like any other field'=>'Bez označení: jako každé jiné pole','Asterisk: marked required, the order goes through without them'=>'Hvězdička: pole jsou označena jako povinná, objednávku ale lze dokončit i bez nich','Required for companies: no order without them (recommended)'=>'Povinné pro firmy: bez vyplnění polí objednávku nelze dokončit (doporučeno)','Require DIČ'=>'Vyžadovat DIČ','A company from the shop\'s own country that enters its IČO has to enter its DIČ too, and "Required for companies" asks for it. Off by default: non-profit organizations may have an IČO but no DIČ.'=>'Firma ze země obchodu, která zadá IČO, musí zadat i DIČ; v režimu „Povinné pro firmy“ je DIČ povinné. Ve výchozím stavu vypnuto: neziskové organizace mohou mít IČO bez DIČ.','Enable validation of VAT number in EU database VIES.'=>'Povolit ověřování hodnoty DIČ v evropské databázi VIES.','Enable VAT exemption for valid EU VAT numbers'=>'Povolit osvobození od DPH pro platná DIČ z EU','To enable this feature, turn on taxes in your store.'=>'Chcete-li tuto funkci povolit, zapněte ve svém obchodě daně.','To enable this feature, set your base country to one of the EU VAT countries.'=>'Chcete-li tuto funkci povolit, nastavte jako zemi obchodu jednu ze zemí EU s DPH.','Check Business ID, DIČ and IČ DPH in the Finančná správa lists, downloaded daily (about 70 MB) into a SQLite file in the uploads folder (about 190 MB). Business IDs not in the lists yet (new, or not registered for tax) are accepted without autofill. IČ DPH is checked in VIES only when the lists do not have it.'=>'Ověřit IČO, DIČ a IČ DPH v seznamech Finanční správy SR, které se denně stahují (asi 70 MB) do souboru SQLite ve složce uploads (asi 190 MB). IČO, které v seznamech ještě není (nová firma nebo firma neregistrovaná k dani), se přijme bez automatického vyplnění. IČ DPH se ověřuje ve VIES, jen pokud ho seznamy neobsahují.','Czech Republic'=>'Česko','Enable validation of Business ID in Czech database ARES.'=>'Povolit ověřování hodnoty IČO v databázi ARES.','CZ: Validate and autofill based on ARES'=>'CZ: Ověřit a automaticky vyplňovat podle ARESu','Enable company name search, and autofill and validation for Company, VAT number, Address, City, and Postcode fields based on Czech database ARES. Requires checked the option above.'=>'Povolit vyhledávání podle názvu firmy a automatické vyplnění a ověření polí Firma, DIČ, Adresa, Město a PSČ podle české databáze ARES. Vyžaduje zapnutou volbu výše.','Slovakia'=>'Slovensko','SK: Validate and autofill based on Finančná správa'=>'SK: Ověřit a automaticky vyplňovat podle Finanční správy SR','Enable company name search, and autofill and validation for Company, DIČ, IČ DPH, Address, City, and Postcode fields. Requires checked the option above.'=>'Povolit vyhledávání podle názvu firmy a automatické vyplnění a ověření polí Firma, DIČ, IČ DPH, Adresa, Město a PSČ. Vyžaduje zapnutou volbu výše.','SK: Disable DIČ / IČ DPH match check'=>'SK: Vypnout kontrolu shody DIČ / IČ DPH','Disable validation that IČ DPH must equal "SK" + DIČ. Some non-profit organizations have IČ DPH that does not match their DIČ.'=>'Vypnout kontrolu, zda IČ DPH odpovídá „SK“ + DIČ. Některé neziskové organizace mají IČ DPH, které jejich DIČ neodpovídá.','European Union'=>'Evropská unie','EU: Validate VAT number in VIES'=>'EU: Ověřit DIČ ve VIES','Business ID only where companies have one'=>'IČO jen tam, kde ho firmy mají','Hide the Business ID field for billing countries other than Slovakia and the Czech Republic, whose companies have no IČO. The list can be changed with the woolab_icdic_ic_countries filter.'=>'Skrýt pole IČO u fakturačních zemí, jejichž firmy IČO nemají (všech kromě Česka a Slovenska). Seznam lze změnit filtrem woolab_icdic_ic_countries.','EU: VAT exempt'=>'EU: Osvobození od DPH','When a check fails'=>'Když ověření selže','Ignore when ARES, Finančná správa or VIES check fails for technical reasons'=>'Ignorovat, když ověření v ARESu, ve Finanční správě SR nebo ve VIES selže z technických důvodů','Allow the creation of an order if the verification of the Business ID in ARES or Finančná správa, or the VAT number in the European VIES database fails for technical reasons.'=>'Umožnit vytvoření objednávky, pokud se z technických důvodů nepodaří ověřit IČO v ARESu nebo ve Finanční správě SR, nebo DIČ v evropské databázi VIES.','Leave empty to follow the theme.'=>'Nechte prázdné, má-li se použít barva šablony.','Status icons'=>'Stavové ikony','The padlock on the company name and Business ID after an autofill, and the checkmark on the other filled-in fields.'=>'Zámek u názvu firmy a IČO po automatickém vyplnění a zatržítko u ostatních vyplněných polí.','Verified'=>'Ověřeno','Padlock and checkmark. Leave empty for green (#007518).'=>'Zámek a zatržítko. Nechte prázdné pro zelenou (#007518).','Clear'=>'Vymazání','The X the padlock turns into. Leave empty for red (#a00).'=>'X, na které se změní zámek. Nechte prázdné pro červenou (#a00).','Company name suggestions'=>'Návrhy názvů firem','By default the list takes its colours from the company field.'=>'Ve výchozím stavu přebírá seznam barvy z pole s názvem firmy.','Background'=>'Pozadí','Text'=>'Text','Border'=>'Okraj','Highlighted suggestion'=>'Zvýrazněný návrh','Leave empty for a tint of the text colour.'=>'Nechte prázdné pro odstín barvy textu.','Corner radius'=>'Zaoblení rohů','In pixels. Leave empty for the company field\'s own.'=>'V pixelech. Nechte prázdné pro zaoblení pole s názvem firmy.','Finančná správa lists'=>'Seznamy Finanční správy SR','The DIČ and IČ DPH lists the Slovak checks run against, imported daily.'=>'Denně importované seznamy DIČ a IČ DPH, podle kterých se ověřují slovenské údaje.','%1$s (%2$s ago)'=>'%1$s (stáří: %2$s)','Off. Enable "SK: Validate in Finančná správa" in %s.'=>'Vypnuto. Zapněte „SK: Ověřit v seznamech Finanční správy SR“ v části %s.','Validation'=>'Ověřování','Up to date'=>'Aktuální','Older than a week: Slovak numbers are checked in VIES only, or let through when "ignore when the check fails" is on.'=>'Starší než týden: slovenská čísla se ověřují jen ve VIES, nebo se přijmou, je-li zapnuto „ignorovat, když ověření selže“.','Not imported yet'=>'Zatím neimportováno','Status'=>'Stav','Last import'=>'Poslední import','%1$s DIČ, %2$s IČ DPH'=>'%1$s DIČ, %2$s IČ DPH','Database'=>'Databáze','The file is missing, the next import creates it again.'=>'Soubor chybí, nejbližší import ho vytvoří znovu.','Last failed import'=>'Poslední neúspěšný import','Not scheduled, it is scheduled again on the next page load.'=>'Nenaplánováno, naplánuje se znovu při nejbližším načtení stránky.','%s, overdue: WP-Cron has not run since. It runs on page visits, or set up a server cron job for wp-cron.php.'=>'%s, zpožděno: WP-Cron od té doby neběžel. Spouští se při návštěvách webu, případně nastavte serverový cron pro wp-cron.php.','Next import'=>'Další import','PHP extensions'=>'Rozšíření PHP','Import now'=>'Importovat nyní','Every import is logged in %s.'=>'Každý import se zapisuje do %s.','WooCommerce → Status → Logs'=>'WooCommerce → Stav → Protokoly','Set by the %s filter in the theme or a plugin.'=>'Nastaveno filtrem %s v šabloně nebo v pluginu.','IČO DIČ'=>'IČO DIČ','Appearance'=>'Vzhled','Finančná správa'=>'Finanční správa SR','Enter a valid Business ID'=>'Zadejte platnou hodnotu IČO','%1$s is not corresponding to %2$s.'=>'%1$s neodpovídá údajům v registru %2$s.' . "\0" . '%1$s neodpovídají údajům v registru %2$s.' . "\0" . '%1$s neodpovídají údajům v registru %2$s.','%s is not corresponding to Finančná správa.'=>'%s neodpovídá údajům Finanční správy SR.' . "\0" . '%s neodpovídají údajům Finanční správy SR.' . "\0" . '%s neodpovídají údajům Finanční správy SR.','%s is not corresponding to ARES.'=>'%s neodpovídá údajům v ARESu.' . "\0" . '%s neodpovídají údajům v ARESu.' . "\0" . '%s neodpovídají údajům v ARESu.','field labelThe billing country does not correspond to the country of the %s.'=>'Fakturační země neodpovídá zemi, která vydala %s.','field labelThe shipping country does not correspond to the country of the %s.'=>'Země doručení neodpovídá zemi, která vydala %s.','field label%s has not a correct format.'=>'%s nemá správný formát.','field labelEnter a valid %s.'=>'Zadejte platné %s.','field labelCould not validate %s.'=>'%s se nepodařilo ověřit.','%1$s or %2$s is not valid.'=>'%1$s nebo %2$s není platné.','Tax ID does not belong to the entered Business ID.'=>'DIČ nepatří k zadanému IČO.','Could not validate Tax ID.'=>'DIČ se nepodařilo ověřit.']];